"use strict";
var TIMESTAMP = new RegExp(
  '^([0-9][0-9][0-9][0-9])-([0-9][0-9]?)-([0-9][0-9]?)' +
  '[Tt]([0-9][0-9]?):([0-9][0-9]):([0-9][0-9])(?:\\.([0-9]*))?$');

// The milliseconds of a timestamp: the fraction starts as the number 0,
// holds its digits as a string while it is padded, and ends as a number.
function millis(data) {
  var match, fraction = 0, delta = null;
  match = TIMESTAMP.exec(data);
  if (match === null) throw new Error('Date resolve error');
  if (match[7]) {
    fraction = match[7].slice(0, 3);
    while (fraction.length < 3) {
      fraction += '0';
    }
    fraction = +fraction;
  }
  if (delta) fraction -= delta;
  return Date.UTC(+match[1], +match[2] - 1, +match[3], +match[4], +match[5], +match[6], fraction);
}

function State(input) {
  this.input = input;
  this.position = 0;
  this.line = 0;
  this.lineStart = 0;
}

function snippet(mark) {
  var start = mark.position, text = mark.buffer;
  return text.slice(0, start) + '<' + text.slice(start) + '>';
}

function MarkError(reason, mark) {
  Error.call(this);
  this.name = 'MarkError';
  this.reason = reason;
  this.mark = mark;
  this.message = reason + ' (' + (mark.line + 1) + ':' + (mark.column + 1) + ')';
}
MarkError.prototype = Object.create(Error.prototype);
MarkError.prototype.constructor = MarkError;

// The error's mark is an object literal that gains its snippet afterwards.
function generateError(state, message) {
  var mark = {
    buffer:   state.input,
    position: state.position,
    line:     state.line,
    column:   state.position - state.lineStart
  };
  mark.snippet = snippet(mark);
  return new MarkError(message, mark);
}

function errorAt(input, position, message) {
  var state = new State(input);
  for (var i = 0; i < position && i < input.length; i++) {
    state.position++;
    if (input[i] === '\n') { state.line++; state.lineStart = state.position; }
  }
  if (state.position >= input.length) throw generateError(state, message);
  return 'no error at ' + state.position;
}

// A number binding that `+=` turns into a string.
function label(n) {
  var width = 10;
  width += 'px';
  return n + ' ' + width;
}

// A sum that becomes a string concatenation once a string arrives.
function total(values) {
  var sum = 0;
  for (var i = 0; i < values.length; i++) sum += values[i];
  return sum;
}

module.exports = { millis: millis, errorAt: errorAt, label: label, total: total };
